import sys
import math

def compute_gcd(arr):
    """Compute the GCD of an array of integers"""
    if not arr:
        return 0

    current_gcd = arr[0]
    for num in arr[1:]:
        current_gcd = math.gcd(current_gcd, num)
        if current_gcd == 1:
            break  # GCD can't be smaller than 1
    return current_gcd

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    target = compute_gcd(arr)

    if target in arr:
        print(target)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
"}

