import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    q = int(next(it))

    # Initialize monitor with infinite times (no broken pixels)
    # Use 0-indexed coordinates
    monitor = [[float('inf')] * m for _ in range(n)]

    for _ in range(q):
        xi = int(next(it)) - 1  # Convert to 0-indexed
        yi = int(next(it)) - 1
        ti = int(next(it))
        monitor[xi][yi] = ti

    min_time = float('inf')

    # Check each possible k x k square
    for top in range(n - k + 1):
        for left in range(m - k + 1):
            # Check if all pixels in this square are broken
            all_broken = True
            square_max_time = 0

            for i in range(k):
                for j in range(k):
                    row = top + i
                    col = left + j
                    time = monitor[row][col]

                    if time == float('inf'):
                        all_broken = False
                        break

                    square_max_time = max(square_max_time, time)
                if not all_broken:
                    break

            if all_broken:
                min_time = min(min_time, square_max_time)

    if min_time == float('inf'):
        print(-1)
    else:
        print(min_time)

if __name__ == "__main__":
    solve()
"}

