n, m = map(int, input().split())
x, y = map(int, input().split())

# Read roads
roads = []
for _ in range(m):
    u, v, w = map(int, input().split())
    roads.append((u, v, w))

# Read taxi info
taxi_info = []
for _ in range(n):
    ti, ci = map(int, input().split())
    taxi_info.append((ti, ci))

# Run Dijkstra from each node to get shortest distances
import heapq
INF = float('inf')
distances = [[INF] * (n + 1) for _ in range(n + 1)]

for start in range(1, n + 1):
    dist = [INF] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in roads:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    distances[start] = dist

# Build new graph with taxi edges
new_graph = [[] for _ in range(n + 1)]
for i in range(1, n + 1):
    ti, ci = taxi_info[i - 1]
    for j in range(1, n + 1):
        if distances[i][j] <= ti:
            new_graph[i].append((j, ci))

# Find shortest path in new graph using Dijkstra
min_cost = [INF] * (n + 1)
min_cost[x] = 0
pq = [(0, x)]
while pq:
    cost, u = heapq.heappop(pq)
    if cost > min_cost[u]:
        continue
    for v, c in new_graph[u]:
        if min_cost[v] > min_cost[u] + c:
            min_cost[v] = min_cost[u] + c
            heapq.heappush(pq, (min_cost[v], v))

if min_cost[y] == INF:
    print(-1)
else:
    print(min_cost[y])
"}

