if n == 1 or m == 1:
    print(-1)
else:
    # Create a 2D array of size n x m
    grid = [[0] * m for _ in range(n)]

    # Fill the grid
    for i in range(n):
        if i % 2 == 0:  # even row
            # Fill from left to right, but skip every other cell
            val = i * m + 1
            for j in range(m):
                if j % 2 == 0:
                    grid[i][j] = val
                    val += 1
                else:
                    val += 1
        else:  # odd row
            # Fill from right to left, but skip every other cell
            val = i * m + 1
            for j in range(m):
                if j % 2 == 1:
                    grid[i][j] = val
                    val += 1
                else:
                    val += 1

    # Print the grid
    for row in grid:
        print(' '.join(map(str, row)))
