def is_square(p1, p2, p3, p4):
    """Check if four points form a square"""
    def dist(p, q):
        return (p[0]-q[0])**2 + (p[1]-q[1])**2

    dists = [dist(p1,p2), dist(p1,p3), dist(p1,p4),
             dist(p2,p3), dist(p2,p4), dist(p3,p4)]
    dists.sort()

    # For a square, we should have 4 equal sides and 2 equal diagonals
    # and the diagonal should be sqrt(2) times the side
    side_sq = dists[0]
    diagonal_sq = dists[4]

    # Check if the smaller distances are sides
    if dists[1] == dists[2] == dists[3] == side_sq:
        # Check if the larger distances are diagonals
        if dists[4] == dists[5] == diagonal_sq:
            # Check if diagonal is sqrt(2) times side
            # Since we're comparing squared distances:
            # diagonal_sq should be 2 * side_sq
            if diagonal_sq == 2 * side_sq:
                return True
    return False

def solve():
    n = int(input())

    for _ in range(n):
        positions = []
        for _ in range(4):
            x, y, a, b = map(int, input().split())
            positions.append((x, y, a, b))

        min_moves = float('inf')

        # For each mole, generate possible positions after 0, 1, 2, 3 moves
        moles = []
        for x, y, a, b in positions:
            states = []
            for moves in range(4):
                if moves == 0:
                    nx, ny = x, y
                elif moves == 1:
                    nx, ny = a + b - y, b + x - a
                elif moves == 2:
                    nx, ny = 2*a - x, 2*b - y
                elif moves == 3:
                    nx, ny = a - b + y, a + b - x
                states.append((nx, ny))
            moles.append(states)

        # Try all combinations of positions
        for p1 in moles[0]:
            for p2 in moles[1]:
                for p3 in moles[2]:
                    for p4 in moles[3]:
                        # Check if these 4 points form a square
                        if is_square((p1[0], p1[1]), (p2[0], p2[1]),
