def is_square(p1, p2, p3, p4):
    """Check if four points form a square"""
    def dist(p, q):
        return (p[0]-q[0])**2 + (p[1]-q[1])**2

    dists = [dist(p1,p2), dist(p1,p3), dist(p1,p4),
             dist(p2,p3), dist(p2,p4), dist(p3,p4)]

    # Find the smallest distance (should be side length)
    side_sq = min(dists)

    # Count how many distances equal side_sq
    count_side = 0
    for d in dists:
        if d == side_sq:
            count_side += 1

    # If exactly 4 distances are equal, they could be sides
    if count_side == 4:
        # The remaining 2 should be diagonals
        diagonal_sq = dists[0]
        for d in dists:
            if d != side_sq:
                diagonal_sq = d
                break

        if dists.count(diagonal_sq) == 2:
            # Check if diagonal is sqrt(2) times side
            if diagonal_sq == 2 * side_sq:
                return True

    return False

def solve():
    n = int(input())

    for _ in range(n):
        positions = []
        for _ in range(4):
            x, y, a, b = map(int, input().split())
            positions.append((x, y, a, b))

        min_moves = float('inf')

        # For each mole, generate possible positions after 0, 1, 2, 3 moves
        moles = []
        for x, y, a, b in positions:
            states = []
            for moves in range(4):
                if moves == 0:
                    nx, ny = x, y
                elif moves == 1:
                    nx, ny = a + b - y, b + x - a
                elif moves == 2:
                    nx, ny = 2*a - x, 2*b - y
                elif moves == 3:
                    nx, ny = a - b + y, a + b - x
                states.append((nx, ny))
            moles.append(states)

        # Try all combinations of positions
        for p1 in moles[0]:
            for p2 in moles[1]:
                for p3 in moles[2]:
                    for p4 in moles[3]:
                        # Check if these 4 points form a square
                        if is_square((p1[0], p1[1]), (p2[0], p2[1]),
                                    (p3[0], p3[1]), (p4[0], p4[1])):
                            # Count the number of moves
                            moves = 0
                            for i in range(4):
                                for j in range(4):
                                    if moles[i][j] == (p1 if i==0 else p2 if i==1 else p3 if i==2 else p4):
                                        moves += j
                                        break
                            min_moves = min(min_moves, moves)

        if min_moves == float('inf'):
            print(-1)
        else:
            print(min_moves)

