def count_square_free(n):
    if n == 0:
        return 0

    # Find all primes up to sqrt(n) using sieve
    def sieve(limit):
        is_prime = [True] * (limit + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(limit**0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False
        return [i for i, prime in enumerate(is_prime) if prime]

    primes = sieve(int(n**0.5) + 1)

    # Count numbers divisible by at least one square of a prime
    count = 0
    for subset in range(1, 1 << len(primes)):
        bits = bin(subset).count('1')
        # Calculate product of squares
        product = 1
        for j in range(len(primes)):
            if subset & (1 << j):
                product *= primes[j] * primes[j]
        # Use inclusion-exclusion
        if bits % 2 == 1:
            count += n // product
        else:
            count -= n // product

    # Subtract from total
    return n - count

def main():
    n = int(sys.stdin.read().strip())
    print(count_square_free(n))

if __name__ == "__main__":
    main()
