for _ in range(T):
    x, y = map(int, input().split())

    # If y == x, we can always just stop
    if y == x:
        print("YES")
    elif y > x:
        # If y > x, we need to increase
        # We can always apply the 3a/2 spell at some point
        # Let's check if we can reach y from x
        if x % 2 == 0:
            # x is even, we can do 3x/2
            if 3 * x / 2 == y:
                print("YES")
            else:
                # We need to see if we can reach y by first decreasing
                # and then increasing
                # We can decrease by 1 to make it odd
                # Let's check if we can reach y by going to x-1, then 3(x-1)/2
                if (3 * (x - 1) / 2) == y:
                    print("YES")
                else:
                    print("NO")
        else:
            # x is odd, we can do x-1 (even)
            # Then we can do 3(x-1)/2
            if 3 * (x - 1) / 2 == y:
                print("YES")
            else:
                print("NO")
