import sys
from math import comb, factorial

def count_ways_with_leading_zero_allowed(k, a):
    """Count k-length sequences (with leading zeroes allowed) that satisfy constraints"""
    min_total = sum(a)
    if min_total > k:
        return 0

    # Use memoization to avoid recomputation
    from functools import lru_cache

    @lru_cache(None)
    def recurse(pos, current_counts):
        if pos == k:
            for i in range(10):
                if current_counts[i] < a[i]:
                    return 0
            return 1

        total = 0
        for digit in range(10):
            new_counts = list(current_counts)
            new_counts[digit] += 1
            total += recurse(pos + 1, tuple(new_counts))
        return total

    return recurse(0, tuple([0]*10))

def count_ways_with_leading_zero_disallowed(k, a):
    """Count k-length sequences with no leading zeroes that satisfy constraints"""
    min_total = sum(a)
    if min_total > k:
        return 0

    # First digit: 1-9
    # Remaining digits: 0-9
    # We need to count sequences where first digit is non-zero

    # Instead of separate count, let's just count sequences with leading zeroes allowed
    # and subtract those with leading zeroes

    count_with_leading_zero_allowed = count_ways_with_leading_zero_allowed(k, a)

    # Count sequences where first digit is zero
    # Fix first digit to 0, then count remaining k-1 positions
    count_with_leading_zero = 0

    if a[0] == 0:
        # We can have leading zero
        count_with_leading_zero = count_ways_with_leading_zero_allowed(k - 1, a)

    return (count_with_leading_zero_allowed - count_with_leading_zero) % (10**9 + 7)

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    MOD = 10**9 + 7

    result = 0

    for k in range(1, n + 1):
        result = (result + count_ways_with_leading_zero_disallowed(k, a)) % MOD

    print(result)

solve()
