import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    result = 0
    for i in range(n):
        # a[i] is 1-indexed position in new list
        # i+1 is 1-indexed position in new list
        # a[i] is old position
        # If there exists j < i such that a[j] > a[i], then i-th thread has a message
        has_message = False
        for j in range(i):
            if a[j] > a[i]:
                has_message = True
                break
        if has_message:
            result += 1

    print(result)

if __name__ == "__main__":
    solve()
"}

