segments = []
for i in range(n):
    l, r = map(int, input().split())
    segments.append((l, r, i + 1))  # Store index (1-based)

# Sort by right endpoint
segments.sort(key=lambda x: x[1])

coverage = {}
removed = []

for l, r, idx in segments:
    # Check if adding this segment would cause any point to exceed k
    exceeds = False
    for point in range(l, r + 1):
        if coverage.get(point, 0) >= k:
            exceeds = True
            break

    if not exceeds:
        # Add this segment
        for point in range(l, r + 1):
            coverage[point] = coverage.get(point, 0) + 1
    else:
        # Remove this segment
        removed.append(idx)

print(len(removed))
print(' '.join(map(str, removed)))
