def can_erase_block(a, i, j):
    """Check if we can erase elements from index i to j inclusive."""
    n = len(a)

    # Check if there are elements before the block
    if i > 0:
        # The element before the block + 1 should not exist
        prev_val = a[i-1]
        # Check if prev_val + 1 exists in the remaining array (after the block)
        if (prev_val + 1) in a[j+1:]:
            return False

    # Check if there are elements after the block
    if j < n - 1:
        # The element after the block - 1 should not exist
        next_val = a[j+1]
        # Check if next_val - 1 exists in the remaining array (before the block)
        if (next_val - 1) in a[:j]:
            return False

    # Check if the gap between the block is at least 2 (if both before and after exist)
    if i > 0 and j < n - 1:
        if a[j+1] - a[i-1] < 2:
            return False

    return True

