def check_group(group, students):
    """Check if a group of students works calmly."""
    n = len(group)
    for i in range(n):
        x = group[i]
        found = False
        for j in range(n):
            y = group[j]
            if i == j:
                continue
            # y knows an algorithm that x doesn't know
            if (y & (~x)) != 0:
                found = True
                break
        if not found:
            return False
    return True

def max_calm_group_sum(n, a, b):
    """Find the maximum sum of b_i for a calm group."""
    # Sort by skill level descending
    students = sorted(zip(b, a), key=lambda x: -x[0])
    max_sum = 0

    # Try all possible group sizes
    for size in range(2, n + 1):
        # Try all combinations of students with highest b_i
        for i in range(n - size + 1):
            group = students[i:i+size]
            if check_group(group, students):
                sum_b = sum(b for b, a in group)
                if sum_b > max_sum:
                    max_sum = sum_b

    return max_sum

