                # Check each column
                for c in range(1, n + 1):
                    blocked_cells = blocked[c]

                    # Check if we can place a vertical domino covering this column
                    # We need one cell blocked and one cell free
                    if len(blocked_cells) == 1:
                        # Only one cell blocked in this column
                        # The other cell is free, so we can place a vertical domino
                        # covering this column
                        has_vertical = True
                        break

                if has_vertical:
                    print("YES")
                else:
                    print("NO")
        else:
            # Odd number of blocked cells
