import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        # Read n edges
        edges = []
        for _ in range(n):
            u = int(next(it)) - 1
            v = int(next(it)) - 1
            edges.append((u, v))

        # Build the graph
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # Find all simple paths (undirected, distinct vertices)
        # Since n is small for testing, we can use DFS
        all_paths = set()

        def dfs(node, path):
            # path is a tuple of vertices
            if len(path) > 1:
                all_paths.add(tuple(path))

            for neighbor in graph[node]:
                if neighbor not in path:
                    dfs(neighbor, path + (neighbor,))

        for i in range(n):
            dfs(i, (i,))

        print(len(all_paths))

if __name__ == "__main__":
    solve()
