def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))

        # Build tree
        tree = [[] for _ in range(n + 1)]
        for i in range(2, n + 1):
            parent = int(next(data))
            tree[parent].append(i)
            tree[i].append(parent)  # undirected

        # Compute depth of each node using BFS
        from collections import deque
        depth = [0] * (n + 1)
        visited = [False] * (n + 1)
        queue = deque([1])
        visited[1] = True

        while queue:
            u = queue.popleft()
            for v in tree[u]:
                if not visited[v]:
                    visited[v] = True
                    depth[v] = depth[u] + 1
                    queue.append(v)

        # Read values for nodes 2..n
        values = [0] * (n + 1)
        for i in range(2, n + 1):
            values[i] = int(next(data))

        # Compute depth levels
        max_depth = depth[1] + 1  # root is depth 0

        # For each depth level from 0 to max_depth - 1
        result = 0

        for i in range(max_depth - 1):
            nodes_i = []
            for v in range(2, n + 1):
                if depth[v] == i:
                    nodes_i.append(values[v])

            nodes_i1 = []
            for v in range(2, n + 1):
                if depth[v] == i + 1:
                    nodes_i1.append(values[v])

            best = 0
            for a_r in nodes_i:
                for a_b in nodes_i1:
                    best = max(best, abs(a_r - a_b))

            result += best

        print(result)

if __name__ == "__main__":
    solve()
