for peak in range(n):
    # For increasing part: make a[0..peak] strictly increasing
    # Start from the end and work backwards
    for i in range(peak, -1, -1):
        if i == peak:
            # Peak value
            pass
        elif i > 0:
            if a[i] <= a[i-1]:
                # Need to increase a[i]
                required = a[i-1] + 1
                min_modifications = min(min_modifications, required - a[i])
                a[i] = required
        else:
            # First element
            pass

    # For decreasing part: make a[peak..n-1] strictly decreasing
    # Start from the end and work forwards
    for i in range(peak, n):
        if i == peak:
            # Peak value
            pass
        elif i < n - 1:
            if a[i] <= a[i+1]:
                # Need to increase a[i+1]
                required = a[i] - 1
                min_modifications = min(min_modifications, required - a[i+1])
                a[i+1] = required
        else:
            # Last element
            pass

print(min_modifications)

