    # Calculate required values for increasing part
    increasing = [a[0]]
    for i in range(1, peak + 1):
        if a[i] <= increasing[-1]:
            required = increasing[-1] + 1
            increasing.append(required)
        else:
            increasing.append(a[i])

    # Calculate required values for decreasing part
    decreasing = [a[peak]]
    for i in range(peak + 1, n):
        if a[i] >= decreasing[-1] - 1:
            required = decreasing[-1] - 1
            decreasing.append(required)
        else:
            decreasing.append(a[i])

    # Calculate total modifications
    modifications = 0
    for i in range(n):
        if i <= peak:
            # Increasing part
            modifications += abs(increasing[i] - a[i])
        else:
            # Decreasing part
            modifications += abs(decreasing[i] - a[i])

    min_modifications = min(min_modifications, modifications)

