        # At least 6 houses, covers 3 houses
        farthest = 5
    else:
        # 4 or 5 houses, covers remaining houses
        farthest = n - 1

    # Place station 1
    if farthest == 3:
        stations[1] = x[3]
    else:
        stations[1] = (x[3] + x[farthest]) / 2

