def solve():
    n = int(input())
    s = input().strip()

    # Find matching pairs using a stack
    match = [-1] * n
    stack = []
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            if stack:
                j = stack.pop()
                match[i] = j
                match[j] = i

    # Now try to balance the depths
    # We'll maintain two stacks and try to balance
    stack_red = []
    stack_blue = []
    result = ['0'] * n

    # Try to assign brackets to colors
    for i in range(n):
        j = match[i]

        if j != -1:
            # This is a closing bracket that matches a previous opening
            if result[j] == '0':
                # The matching opening is red, so this closing must be red
                if result[i] == '0':
                    stack_red.append(i)
                else:
                    # Switch to red
                    result[i] = '0'
                    stack_red.append(i)
                    stack_blue.pop()
            else:
                # The matching opening is blue, so this closing must be blue
                if result[i] == '1':
                    stack_blue.append(i)
                else:
                    # Switch to blue
                    result[i] = '1'
                    stack_blue.append(i)
                    stack_red.pop()

    # Check if we need to balance more
    while len(stack_red) > len(stack_blue) + 1:
        # Find a point to switch
        for i in range(n):
            if result[i] == '0':
                # Try to switch to blue
                result[i] = '1'
                stack_red.pop()
                stack_blue.append(i)
                break

    print(''.join(result))

solve()
