def parse_action(line):
    parts = line.split()

    # Format: "X posted on Y's wall"
    # Format: "X commented on Y's post"
    # Format: "X likes Y's post"

    # Find the action verb
    if parts[1] == "posted":
        action = 15
    elif parts[1] == "commented":
        action = 10
    elif parts[1] == "likes":
        action = 5
    else:
        raise ValueError("Unknown action")

    # Find the owner of the post
    if parts[2] == "on":
        # Format: "X posted on Y's wall"
        owner = parts[4].replace("'", "")
        wall = True
    elif parts[2] == "on":
        # Format: "X commented on Y's post" or "X likes Y's post"
        owner = parts[4].replace("'", "")
        wall = False
    else:
        raise ValueError("Unknown format")

    return parts[0], owner, action, wall

def main():
    import sys
    data = sys.stdin.read().splitlines()

    if not data:
        return

    your_name = data[0].strip()
    n = int(data[1].strip())

    # Initialize priority scores
    priority = {}  # key: name, value: score

    for i in range(2, 2 + n):
        line = data[i].strip()
        if not line:
            continue

        try:
            X, Y, action, wall = parse_action(line)
        except IndexError:
            print(f"Error parsing line: {line}", file=sys.stderr)
            continue

        # Update priority for both directions
        if X not in priority:
            priority[X] = 0
        if Y not in priority:
            priority[Y] = 0

        priority[X] += action
        priority[Y] += action

    # Filter out ourselves and sort
    results = []
    for name in priority:
        if name != your_name:
            results.append((priority[name], name))

    # Sort by priority (descending), then lexicographically (ascending)
    results.sort(key=lambda x: (-x[0], x[1]))

    # Output
    for score, name in results:
        print(name)

if __name__ == "__main__":
    main()
