def solve():
    # Read t-shirt counts (S, M, L, XL, XXL, XXXL)
    counts = list(map(int, input().split()))

    # Read number of participants
    n = int(input())

    # Read participants' preferences
    participants = []
    for _ in range(n):
        line = input().strip()
        if "," in line:
            sizes = line.split(",")
            participants.append((sizes[0], sizes[1]))
        else:
            participants.append((line, None))

    # Mapping from size string to index
    def size_to_idx(size):
        if len(size) == 1:
            if size == 'S':
                return 0
            elif size == 'M':
                return 1
            elif size == 'L':
                return 2
        elif len(size) == 2:
            if size == 'XL':
                return 3
        elif len(size) == 3:
            if size == 'XXL':
                return 4
        elif len(size) == 4:
            if size == 'XXXL':
                return 5
        raise ValueError(f"Unknown size: {size}")

    # Process participants greedily from left to right
    result = []
    for size1, size2 in participants:
        if size2 is None:
            # Single size
            idx = size_to_idx(size1)
            if counts[idx] == 0:
                print("NO")
                return
            counts[idx] -= 1
            result.append(size1)
        else:
            # Two sizes, neighboring
            idx1 = size_to_idx(size1)
            idx2 = size_to_idx(size2)

            # Try leftmost size first
            if counts[idx1] > 0:
                counts[idx1] -= 1
                result.append(size1)
            else:
                # Try right size
                if counts[idx2] == 0:
                    print("NO")
                    return
                counts[idx2] -= 1
                result.append(size2)

    print("YES")
    for size in result:
        print(size)

solve()
