def solve():
    # Read t-shirt counts for S, M, L, XL, XXL, XXXL
    counts = list(map(int, input().split()))
    n = int(input())

    # Read participants' preferences
    participants = []
    for _ in range(n):
        pref = input().strip()
        if ',' in pref:
            # Two neighboring sizes
            sizes = pref.split(',')
            participants.append((False, sizes))
        else:
            # Single size
            participants.append((True, pref))

    # Create a mapping from size name to index
    size_to_idx = {'S': 0, 'M': 1, 'L': 2, 'XL': 3, 'XXL': 4, 'XXXL': 5}

    # Convert counts to a list of integers
    counts = [counts[i] for i in range(6)]

    # First, try to satisfy participants with single size preferences
    result = []
    for pref in participants:
        if pref[0]:  # Single size
            size = pref[1]
            idx = size_to_idx[size]
            if counts[idx] > 0:
                counts[idx] -= 1
                result.append(size)
            else:
                print("NO")
                return

    # Now handle participants with two neighboring sizes
    # Process from S to XXXL to handle dependencies
    for pref in participants:
        if not pref[0]:  # Two sizes
            sizes = pref[1]
            idx1 = size_to_idx[sizes[0]]
            idx2 = size_to_idx[sizes[1]]

            # Check both sizes before assigning
            # One common approach is to always assign the smaller index
            if idx1 < idx2:
                if counts[idx1] > 0:
                    counts[idx1] -= 1
                    result.append(sizes[0])
                else:
                    if counts[idx2] > 0:
                        counts[idx2] -= 1
                        result.append(sizes[1])
                    else:
                        print("NO")
                        return
            else:
                if counts[idx2] > 0:
