                # Positions at this row: j - (row - i) to j + (row - i)
                left = j - (row - i)
                right = j + (row - i)

                # Check if all positions in this row have the same color
                for col in range(left, right + 1):
                    if grid[row][col] != color:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                count += 1

