from collections import Counter

n, m, k = map(int, input().split())

alice = list(map(int, input().split()))
bob = list(map(int, input().split()))

alice_freq = Counter(alice)
bob_freq = Counter(bob)

# Check if Alice has any species that Bob doesn't
has_unique = False
for species in range(1, k + 1):
    if alice_freq.get(species, 0) > 0 and bob_freq.get(species, 0) == 0:
        has_unique = True
        break

if has_unique:
    print("YES")
elif len(alice_freq) < len(bob_freq):
    # Bob has a species that Alice doesn't
    print("NO")
else:
    # They have the same species
    # Check if Alice has more of any species than Bob
    can_alice_win = False
    for species, count in alice_freq.items():
        if bob_freq.get(species, 0) < count:
            can_alice_win = True
            break

    if can_alice_win:
        print("YES")
    else:
        # Alice has equal or fewer of all species
        # Bob could win by making the shared species very heavy
        print("NO")
