# Check if there exists a k x k square that is completely broken by time t
def is_broken_by_time(t):
    # Create prefix sum of broken pixels up to time t
    # pref[i][j] = number of broken pixels in rectangle (1,1)-(i,j)
    pref = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if broken[i][j] <= t:
                pref[i][j] = pref[i-1][j] + pref[i][j-1] - pref[i-1][j-1] + 1
            else:
                pref[i][j] = pref[i-1][j] + pref[i][j-1] - pref[i-1][j-1]

    # Check all k x k squares
    for i in range(1, n - k + 2):
        for j in range(1, m - k + 2):
            # Top-left corner (i,j), bottom-right corner (i+k-1, j+k-1)
            x1, y1 = i, j
            x2, y2 = i + k - 1, j + k - 1

            # Count broken pixels in this square
            total = pref[x2][y2] - pref[x1-1][y2] - pref[x2][y1-1] + pref[x1-1][y1-1]
            if total == k * k:
                return True
    return False

