                balance -= 1

            if balance < min_balance:
                min_balance = balance

        key = (balance, min_balance)
        counts[key] = counts.get(key, 0) + 1

    # Now, find the maximum number of pairs
    result = 0

    # We'll sort sequences by balance and use a greedy two-pointer approach
    # For negative balance sequences, we want to pair them with positive balance sequences

    # Get all sequences sorted by balance
    sequences = []
    for (b, m), count in counts.items():
        sequences.extend([(b, m)] * count)

    # Sort by balance
    sequences.sort()

    # Two pointers: left for negative balance, right for positive balance
    left = 0
    right = len(sequences) - 1

    while left < right:
        b1, m1 = sequences[left]
        b2, m2 = sequences[right]

        # If b1 and b2 have the same absolute value, check if they can pair
        if abs(b1) == abs(b2):
            if b1 + b2 == 0:
                # Check if b1 >= -m2 or b2 >= -m1 (since b1 + b2 = 0, these are equivalent)
                if b1 >= -m2 or b2 >= -m1:
                    result += 1
                    left += 1
                    right -= 1
            else:
                # They shouldn't have the same absolute value if b1 + b2 != 0
                # But this should never happen if sorted correctly
                left += 1
