    # When we milk cow i, cows that see cow i get scared
    # Cows that see cow i: 
    # - If direction[i] == 1 (right), all cows j > i see it
    # - If direction[i] == 0 (left), all cows j < i see it

    # We should milk cows in an order that minimizes the number of unseen cows that see them
    # The optimal strategy: milk cows facing right from right to left, milk cows facing left from left to right

    # Count the number of losses
    losses = 0

    # Milk cows facing right from right to left
    for i in reversed(range(n)):
        if directions[i] == 1:
            # Count cows that see cow i (to its right)
            for j in range(i + 1, n):
                # Cow j sees cow i if cow j faces left
                if directions[j] == 0:
                    losses += 1

    # Milk cows facing left from left to right
    for i in range(n):
        if directions[i] == 0:
            # Count cows that see cow i (to its left)
            for j in range(i):
                # Cow j sees cow i if cow j faces right
                if directions[j] == 1:
                    losses += 1

    print(losses)

if __name__ == "__main__":
