    facing = list(map(int, input().split()))

    total_loss = 0
    milked = set()

    # Milk cows facing right from right to left
    for i in range(n - 1, -1, -1):
        if facing[i] == 1:
            # Count cows that see this cow (i.e., un-milked cows that will get scared)
            for j in range(n):
                if j == i:
                    continue
                if (facing[j] == 1 and i > j) or (facing[j] == 0 and i < j):
                    if j not in milked:
                        total_loss += 1
                        milked.add(j)
            milked.add(i)

    # Milk cows facing left from left to right
    for i in range(n):
        if facing[i] == 0:
            for j in range(n):
                if j == i:
                    continue
                if (facing[j] == 1 and i > j) or (facing[j] == 0 and i < j):
                    if j not in milked:
                        total_loss += 1
                        milked.add(j)
            milked.add(i)

    print(total_loss)

solve()

