from collections import Counter

def max_frames(sticks):
    count = Counter(sticks)

    # Option 1: Make square frames
    max_square = 0
    for length, freq in count.items():
        max_square += freq // 4

    # Option 2: Make rectangular frames
    # For each possible pair of lengths
    max_rect = 0
    for i, (h, freq_h) in enumerate(count.items()):
        for j, (w, freq_w) in enumerate(count.items()):
            if i != j:  # Different lengths
                # We can make min(frequency[h], frequency[w]) rectangular frames
                max_rect = max(max_rect, min(freq_h, freq_w))

    # Option 3: Combine squares and rectangles
    # Use some sticks for squares and some for rectangles
    max_combined = 0
    for length, freq in count.items():
        # Try using k sticks for square frames
        for k in range(0, freq + 1, 4):
            remaining = freq - k
            pairs_remaining = remaining // 2

            # Now make rectangular frames with the remaining sticks
            for i, (h, freq_h) in enumerate(count.items()):
                if h == length:
                    continue  # Skip the length we're using for squares
                for j, (w, freq_w) in enumerate(count.items()):
                    if i != j:
                        frames = min(pairs_remaining, freq_h)
                        max_combined = max(max_combined, frames)

    return max(max_square, max_rect, max_combined)

n = int(input())
sticks = list(map(int, input().split()))
result = max_frames(sticks)
print(result)
