import sys

def count_non_adjacent_ones(n):
    """Count the number of non-adjacent 1s in binary representation of n."""
    binary = bin(n)[2:]
    count = 0
    i = 0
    while i < len(binary):
        if binary[i] == '1':
            count += 1
            i += 1
            # Skip the next bit if it's also '1' (non-adjacent)
            if i < len(binary) and binary[i] == '1':
                i += 1
        else:
            i += 1
    return count

def main():
    n = int(sys.stdin.readline())
    print(count_non_adjacent_ones(n))

if __name__ == "__main__":
    main()
"}

