def solve():
    n, m = map(int, input().split())

    # If there's only 1 column and more than 2 rows, it's impossible
    if m == 1 and n > 2:
        print(-1)
        return

    # If there's only 1 row, just print numbers in order
    if n == 1:
        for i in range(1, n * m + 1):
            print(i, end=' ')
        print()
        return

    # For 2x1 case, it's impossible
    if n == 2 and m == 1:
        print(-1)
        return

    # For 1x1 case
    if n == 1 and m == 1:
        print(1)
        return

    # For 2x1 already handled
    if m == 1:
        print(-1)
        return

    # General case: 2 rows or more
    # Use a checkerboard pattern
    # For even rows, place numbers in ascending order
    # For odd rows, place numbers in descending order
    for i in range(n):
        if i % 2 == 0:
            # Even row: ascending order
            for j in range(m):
                print(i * m + j + 1, end=' ')
        else:
            # Odd row: descending order
            for j in range(m):
                print(i * m + m - j, end=' ')
        print()

solve()
