    # If there's only 1 column and more than 2 rows, it's impossible
    if m == 1 and n > 2:
        print(-1)
        return

    # If there's only 1 row, just print numbers in order
    if n == 1:
        for i in range(1, n * m + 1):
            print(i, end=' ')
        print()
        return

    # For 2x1 case, it's impossible
    if n == 2 and m == 1:
        print(-1)
        return

    # For 1x1 case
    if n == 1 and m == 1:
        print(1)
        return

    # For 2x1 already handled
    if m == 1:
        print(-1)
        return

    # General case: 2 rows or more
    # Use a checkerboard pattern where we alternate between two different sequences

    # Sequence 1: (1*m, 2*m, 1*(m-1), 2*(m-1), ...) for even rows
    # Sequence 2: (2*m, 1*m, 2*(m-1), 1*(m-1), ...) for odd rows

    for i in range(n):
        if i % 2 == 0:
            # Even row: Sequence 1
            for j in range(m):
                if j % 2 == 0:
                    print(i * m + j + 1, end=' ')
                else:
                    print(i * m + m + j, end=' ')
        else:
            # Odd row: Sequence 2
            for j in range(m):
                if j % 2 == 0:
                    print(i * m + m + j, end=' ')
                else:
                    print(i * m + j + 1, end=' ')
        print()

