            for i in range(10):
                if state[i] < a[i]:
                    valid = False
                    break
            if not valid:
                continue

            # Calculate number of valid arrangements (permutations with first digit ≠ 0)
            # For a given digit count configuration, the number of valid numbers is:
            # sum over all valid first digits: count ways to arrange the remaining digits

            valid_arrangements = 0
            for first_digit in range(10):
                if state[first_digit] == 0:
                    continue

                # First digit is first_digit, count how many ways
                remaining_state = list(state)
                remaining_state[first_digit] -= 1

                # Count ways to arrange the remaining m-1 digits
                remaining_state_tuple = tuple(remaining_state)
                if remaining_state_tuple in dp[m-1]:
                    valid_arrangements = (valid_arrangements + dp[m-1][remaining_state_tuple]) % MOD

            total = (total + valid_arrangements) % MOD

