def count_dress_patterns(n, m, grid):
    count = 0

    # Count all valid squares of any size
    # A square of "size" k (where k is the number of layers from top to bottom)
    # has top at (i,j) and bottom at (i+2k, j)
    # The pattern:
    #     A
    #   A A A
    # A A A A A
    # ... and so on ...
    #     A

    for i in range(n):
        for j in range(m):
            # Try all possible sizes starting from 1
            # Maximum size is such that i+2k < n and j-k >= 0 and j+k < m
            k = 1
            while True:
                # Check if all cells in diamond of size k are the same
                all_same = True
                for step in range(k+1):
