    n, a, b, k = map(int, input().split())
    misses = input().strip()
    unshot = [i for i in range(n) if misses[i] == '0']

    # Count how many placements include each position
    coverage = [0] * n

    # For each position, calculate how many placements include it
    for start in range(n - b + 1):
        # Check if all positions from start to start + b - 1 are unshot
        is_valid = True
        for i in range(start, start + b):
            if misses[i] == '1':
                is_valid = False
                break
        if is_valid:
            for i in range(start, start + b):
                coverage[i] += 1

    # Greedy algorithm: pick position with maximum coverage
    result = []
    remaining_placements = []
    for start in range(n - b + 1):
        # Check if all positions from start to start + b - 1 are unshot
        is_valid = True
        for i in range(start, start + b):
            if misses[i] == '1':
                is_valid = False
                break
        if is_valid:
            remaining_placements.append((start, start + b - 1))

    # Greedy algorithm: pick position with maximum coverage
    result = []
    for _ in range(len(remaining_placements)):
        # Find position with maximum coverage
        max_idx = -1
        max_count = -1
        for i in range(n):
            if coverage[i] > max_count:
                max_count = coverage[i]
                max_idx = i

        # If no coverage, there's a problem (shouldn't happen)
        if max_count == 0:
            break

        result.append(max_idx)

        # Remove all placements that include this position
        for idx in range(len(remaining_placements)):
            start, end = remaining_placements[idx]
            if max_idx >= start and max_idx <= end:
                remaining_placements.pop(idx)
                break

    # Output the result
    print(len(result))
    print(' '.join(str(i + 1) for i in result))

