def max_bipartite_matching(graph, n):
    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        if i + 1 <= n:
            adj[i].append(i + 1)

    # Find perfect matching
    match_to = [-1] * (n + 1)
    result = 0

    for u in range(1, n + 1):
        if match_to[u] == -1:
            visited = [False] * (n + 1)
            if dfs(u, adj, match_to, visited):
                result += 1

    return result


def dfs(u, adj, match_to, visited):
    visited[u] = True
    for v in adj[u]:
        if match_to[v] == -1 or (not visited[match_to[v]] and dfs(match_to[v], adj, match_to, visited)):
            match_to[v] = u
            return True
    return False


