import sys

def is_valid(sequence):
    """Check if a sequence is a valid RBS"""
    balance = 0
    for ch in sequence:
        if ch == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def nesting_depth(sequence):
    """Calculate the nesting depth of a sequence"""
    balance = 0
    max_depth = 0
    for ch in sequence:
        if ch == '(':
            balance += 1
            max_depth = max(max_depth, balance)
        else:
            balance -= 1
    return max_depth

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    # Find all valid splits
    valid_splits = []
    for i in range(1, n):
        left = s[:i]
        right = s[i:]
        if is_valid(left) and is_valid(right):
            valid_splits.append((left, right))

    # If no valid splits found, just return the original sequence
    if not valid_splits:
        return

    # For each valid split, find the one with minimum max depth
    best_depth = float('inf')
    best_coloring = None

    for left, right in valid_splits:
        depth_left = nesting_depth(left)
        depth_right = nesting_depth(right)
        max_depth = max(depth_left, depth_right)

        # Build the coloring
        coloring = ['0'] * n
        l_idx = 0
        r_idx = 0
        for i in range(n):
            if l_idx < len(left) and s[i] == left[l_idx]:
                coloring[i] = '0'
