def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    idx = 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1

        a = [0] * n

        # Use a segment tree approach with proper updates

        class SegmentTreeNode:
            def __init__(self, l, r):
                self.l = l
                self.r = r
                self.left = None
                self.right = None
                self.max_len = r - l + 1  # Initially all zeros
                self.max_pos = l  # Position of the leftmost maximum segment
                self.max_len_pos = l  # Position of the leftmost maximum segment

        class SegmentTree:
            def __init__(self, n):
                self.n = n
                self.root = self.build(0, n - 1)

            def build(self, l, r):
                node = SegmentTreeNode(l, r)
                if l == r:
                    return node
                mid = (l + r) // 2
                node.left = self.build(l, mid)
                node.right = self.build(mid + 1, r)
                self.push_up(node)
                return node

            def push_up(self, node):
                # Update max length and position
                if node.left.max_len >= node.right.max_len:
                    node.max_len = node.left.max_len
                    node.max_pos = node.left.max_pos
                    node.max_len_pos = node.left.max_len_pos
                else:
                    node.max_len = node.right.max_len
                    node.max_pos = node.right.max_pos
                    node.max_len_pos = node.right.max_len_pos

            def update(self, l, r, node):
                if node.r < l or node.l > r:
                    return
                if l <= node.l and node.r <= r:
                    node.max_len = 0
                    return

                self.update(l, r, node.left)
                self.update(l, r, node.right)
                self.push_up(node)

            def query_max(self, node):
                # Return (max_len, position, leftmost position)
                if node.max_len == 0:
                    return (0, -1, -1)

                return (node.max_len, node.max_pos, node.max_len_pos)

        seg_tree = SegmentTree(n)

        for i in range(1, n + 1):
            max_len, max_pos, max_len_pos = seg_tree.query_max(seg_tree.root)

            # Determine where to place i
            if max_len % 2 == 1:
                place = (max_pos + max_len_pos) // 2
            else:
                place = (max_pos + max_len_pos - 1) // 2

            a[place] = i

            # Update segment tree to mark this specific position as filled
            seg_tree.update(place, place, seg_tree.root)

        results.append(' '.join(map(str, a)) + ' ')

    sys.stdout.write('\n'.join(results))

if __name__ == "__main__":
    solve()

