import sys

def is_amplifying(line):
    """Check if a line is an amplifying line"""
    stripped = line.lstrip(' ')
    return stripped.startswith('#')

def process_line(line):
    """Process a single line: remove all spaces"""
    return line.replace(' ', '')

def main():
    lines = []
    for line in sys.stdin:
        lines.append(line.rstrip('\n'))  # Remove newline from end

    processed = []
    current = []

    for i, line in enumerate(lines):
        if is_amplifying(line):
            # If we have accumulated non-amplifying lines, concatenate them
            if current:
                processed.extend(current)
                current = []
            # Add the amplifying line
            processed.append(line)
        else:
            # Process non-amplifying line
            processed_line = process_line(line)
            current.append(processed_line)

    # Handle remaining lines
    if current:
        processed.extend(current)

    # Join with newlines and add final newline
    output = '\n'.join(processed) + '\n'
    sys.stdout.write(output)

if __name__ == '__main__':
    main()
