from collections import deque

def solve():
    t = int(input())

    for _ in range(t):
        n, a, b = map(int, input().split())

        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u, v = map(int, input().split())
            adj[u].append(v)
            adj[v].append(u)

        # BFS to find path from a to b
        def bfs_path(start, end):
            parent = {}
            queue = deque([start])
            parent[start] = None

            while queue:
                u = queue.popleft()
                if u == end:
                    break
                for v in adj[u]:
                    if v not in parent:
                        parent[v] = u
                        queue.append(v)

            # Reconstruct path
            path = []
            current = end
            while current is not None:
                path.append(current)
                current = parent[current]
            path.reverse()
            return path

        path = bfs_path(a, b)

        # Check if there's a vertex NOT on the path that is adjacent to the path
        found = False
        for i in range(len(path) - 1):
            u = path[i]
            for v in adj[u]:
                if v != path[i - 1] and v != path[i + 1] and v not in path:
                    found = True
                    break
            if found:
                break

        if found:
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    solve()
