    # Generate all valid octets (0-255)
    octets = []
    for i in range(256):
        # Convert to 3-digit string
        s = f"{i:03d}"
        # Check for leading zeros (only allow if number is 0)
        if i == 0 and len(s) > 1:
            continue
        octets.append(s)
    return octets

