    n = int(input())
    required_digits = list(map(int, input().split()))

    octets = generate_octets()

    beautiful_ips = []

    # Try all combinations of 4 octets
    for octet1 in octets:
        for octet2 in octets:
            for octet3 in octets:
                for octet4 in octets:
                    ip_str = octet1 + octet2 + octet3 + octet4
                    if is_palindrome(ip_str) and contains_exact_digits(ip_str, required_digits):
