def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    difficulties = list(map(int, data[1:1+n]))

    # Count frequency of each difficulty
    freq = Counter(difficulties)

    # Find which difficulties have multiple tasks
    groups = {}
    for i, diff in enumerate(difficulties):
        if diff not in groups:
            groups[diff] = []
        groups[diff].append(i + 1)  # 1-indexed task numbers

    # Check if we can get at least 3 distinct permutations
    can = False
    if any(v >= 3 for v in freq.values()):
        can = True
    elif sum(v >= 2 for v in freq.values()) >= 2:
        can = True

    if not can:
        print("NO")
        return

    # Find which group to permute
    if any(v >= 3 for v in freq.values()):
        # Use the group with size >= 3
        for diff, indices in groups.items():
            if len(indices) >= 3:
                perm_indices = indices
                break
    else:
        # Use two groups with size >= 2
        first_group = None
        second_group = None
        for diff, indices in groups.items():
            if len(indices) >= 2:
                if first_group is None:
                    first_group = indices
                else:
                    second_group = indices
                    break

        perm_indices = first_group

    # Generate 3 permutations of this group
    all_perms = itertools.permutations(perm_indices)
    perms = [list(p) for p in all_perms][:3]

    # Build the final sequence
    result = []
