    line = input().strip()

    # Parse the line: "X [verb] on Y's [object]"
    parts = line.split()

    # X is the first word
    x = parts[0]

    # The verb is the second word
    verb = parts[1]

    # "on" is the third word
    if parts[2] != 'on':
        raise ValueError("Unexpected format")

    # The fourth word should be the owner of the post/wall
    if parts[3] != "'s":
        raise ValueError("Unexpected format")

    # Y is the fifth word
    y = parts[4]

    # The object after "on" is the sixth word
    obj = parts[5]

    # Determine points based on verb and object
    if verb == 'posted' and obj == 'wall':
        points = 15
    elif verb == 'commented' and obj == 'post':
        points = 10
    elif verb == 'likes' and obj == 'post':
        points = 5
    else:
        raise ValueError("Unknown action")

    # Update priority for both X and Y
    if x == your_name or y == your_name:
        # One of them is you, update the other's priority
        if x == your_name:
            other = y
        elif y == your_name:
            other = x
        else:
            # Neither is you, skip (shouldn't happen)
            continue

        if other in priority:
            priority[other] += points
        else:
            priority[other] = points

    else:
