import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    idx += 1
    a = []
    while idx < len(data) and len(a) < n:
        a.append(int(data[idx]))
        idx += 1

    b = []
    while idx < len(data) and len(b) < n:
        b.append(int(data[idx]))
        idx += 1

    max_sum = 0

    # Try all possible subsets
    for mask in range(1, 1 << n):
        if bin(mask).count('1') < 2:
            continue
        group = [i for i in range(n) if mask & (1 << i)]
        valid = True

        # For each student in the group, check if they think they are better than everyone else
        for x in group:
            # Check if there's at least one other student y in the group such that x doesn't think y is worse than x
            found = False
            for y in group:
                if x == y:
                    continue
                if (a[x] & ~a[y]) == 0:
                    found = True
                    break
            if not found:
                valid = False
                break

        if valid:
            total_b = sum(b[i] for i in group)
            if total_b > max_sum:
                max_sum = total_b

    print(max_sum)

if __name__ == "__main__":
    solve()
