            if i > 1 or j < n:
                max_erase = max(max_erase, gap_length)
            else:
                # No elements before or after - can't erase all elements
                if gap_length == n:
                    pass  # Can't erase all elements
                else:
                    max_erase = max(max_erase, gap_length)

