def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()

    idx = 0
    t = int(data[idx])
    idx += 1

    out = []

    for _ in range(t):
        # Skip empty lines
        while idx < len(data) and data[idx] == '\n':
            idx += 1

        if idx >= len(data):
            break

        n = int(data[idx])
        m = int(data[idx+1])
        idx += 2

        row1_blocked = set()
        row2_blocked = set()

        for __ in range(m):
            r = int(data[idx])
            c = int(data[idx+1])
            idx += 2

            if r == 1:
                row1_blocked.add(c)
            else:
                row2_blocked.add(c)

        # Check if we can tile
        # Simple approach: check if no column has both cells blocked
        # and the number of blocked cells has the right parity
        total_blocked = len(row1_blocked) + len(row2_blocked)

        # Check if no column is fully blocked
        full_blocked = False
        for c in range(1, n+1):
            if c in row1_blocked and c in row2_blocked:
                full_blocked = True
                break

        if full_blocked:
            out.append("NO")
            continue

        if n % 2 == 0:
            # Even n, need even number of blocked cells
            if total_blocked % 2 == 0:
                out.append("YES")
            else:
                out.append("NO")
        else:
            # Odd n, need odd number of blocked cells
            if total_blocked % 2 == 1:
                out.append("YES")
            else:
                out.append("NO")

    print("\n".join(out))

solve()
