def count_valid_numbers(n):
    # Convert n to string for digit comparison
    n_str = str(n)
    result = 0

    # Try numbers with each possible length from 1 to len(n_str)
    for length in range(1, len(n_str) + 1):
        # If length is less than len(n_str), all numbers with those digits are valid
        if length < len(n_str):
            result += 2 ** length
        else:
            # If length is equal to len(n_str), we need to be careful
            result += count_valid_numbers_of_length(n_str, length)

    return result

def count_valid_numbers_of_length(n_str, length):
    # We need to count numbers with exactly 'length' digits, all 2 or 4,
    # that are less than or equal to n_str

    # Start counting from 222...2 (length 2's) up to n_str
    start = int('2' * length)
    end = int(n_str)

    # Count how many numbers in [start, end] use only digits 2 and 4
    result = 0
    for i in range(start, end + 1):
        s = str(i)
        if all(ch in '24' for ch in s):
            result += 1

    return result

n = int(input())
