def dijkstra(graph, n, start):
    """Dijkstra's algorithm to find minimum cost path from start to all other nodes"""
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    visited = [False] * (n + 1)

    while True:
        # Find the node with minimum distance that hasn't been visited
        min_dist = float('inf')
        min_node = -1

        for i in range(1, n + 1):
            if not visited[i] and dist[i] < min_dist:
                min_dist = dist[i]
                min_node = i

        if min_node == -1:
            break

        visited[min_node] = True

        # Update distances
        for j in range(1, n + 1):
            if graph[min_node][j] != float('inf') and dist[min_node] + graph[min_node][j] < dist[j]:
                dist[j] = dist[min_node] + graph[min_node][j]

    return dist

# Read input
n, m = map(int, input().split())
x, y = map(int, input().split())

# Initialize graph with Floyd-Warshall
INF = float('inf')
dist = [[INF] * (n + 1) for _ in range(n + 1)]

# Set distance to self as 0
for i in range(1, n + 1):
    dist[i][i] = 0

# Read roads
for _ in range(m):
    u, v, w = map(int, input().split())
    dist[u][v] = min(dist[u][v], w)
    dist[v][u] = min(dist[v][u], w)

# Floyd-Warshall
for k in range(1, n + 1):
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

# Read taxi info
taxi = [[0] * (n + 1) for _ in range(n + 1)]
for i in range(1, n + 1):
    t, c = map(int, input().split())
    taxi[i][0] = t
    taxi[i][1] = c

# Build new graph where we can go from i to j if dist[i][j] <= taxi[i][0]
new_dist = [[INF] * (n + 1) for _ in range(n + 1)]

for i in range(1, n + 1):
    max_dist = taxi[i][0]
    cost = taxi[i][1]

    for j in range(1, n + 1):
        if i != j and dist[i][j] <= max_dist:
            new_dist[i][j] = cost

# Run Dijkstra on new graph
result = dijkstra(new_dist, n, x)

if result[y] == INF:
    print(-1)
else:
    print(result[y])
"}

