grid = [input().strip() for _ in range(n)]

count = 0

for i in range(n):
    for j in range(m):
        # Try all possible diamond sizes centered at (i, j)
        # k is the distance from center to vertex (maximum size)
        # k_max_row = min(i, n-1-i)
        # k_max_col = min(j, m-1-j)
        # k_max = min(k_max_row, k_max_col)
        k_max = min(i, n-1-i, j, m-1-j)

        for k in range(k_max + 1):
            # Check if all positions in the diamond of size k have the same color
            color = grid[i][j]
            all_same = True

            # Check all positions (x, y) where |x - i| + |y - j| <= k
            for dx in range(-k, k + 1):
                for dy in range(-k, k + 1):
                    if abs(dx) + abs(dy) > k:
                        continue
                    x = i + dx
                    y = j + dy
                    if x < 0 or x >= n or y < 0 or y >= m:
                        all_same = False
                        break
                    if grid[x][y] != color:
                        all_same = False
                        break
                if not all_same:
                    break

            if all_same:
                count += 1

print(count)
